CREATE TABLE human_acceptance_decisions(run_id TEXT PRIMARY KEY REFERENCES stage_artifacts(run_id),task_id TEXT NOT NULL REFERENCES tasks(id),generation INTEGER NOT NULL CHECK(generation>0),decision_json TEXT NOT NULL,decision_hash TEXT NOT NULL);
CREATE INDEX human_acceptance_task ON human_acceptance_decisions(task_id,generation);
CREATE TRIGGER immutable_human_acceptance BEFORE UPDATE ON human_acceptance_decisions BEGIN SELECT RAISE(ABORT,'immutable human decision'); END;
CREATE TRIGGER preserve_human_acceptance BEFORE DELETE ON human_acceptance_decisions BEGIN SELECT RAISE(ABORT,'preserve human decision'); END;
CREATE TRIGGER validate_human_acceptance BEFORE INSERT ON human_acceptance_decisions WHEN NOT EXISTS(SELECT 1 FROM stage_artifacts a JOIN stage_runs r ON r.id=a.run_id JOIN tasks t ON t.id=r.task_id JOIN reservations v ON v.run_id=r.id WHERE a.run_id=NEW.run_id AND t.id=NEW.task_id AND t.generation=NEW.generation AND r.generation=NEW.generation AND r.plan_revision=t.plan_revision AND r.role='acceptance' AND r.state='succeeded' AND r.lease_owner='' AND v.state='released' AND v.stop_proof_hash=json_extract(a.record_json,'$.reference.stop_proof_hash') AND t.state IN ('advisory_only','needs_review') AND json_extract(NEW.decision_json,'$.run_id')=r.id AND json_extract(NEW.decision_json,'$.task_id')=t.id AND json_extract(NEW.decision_json,'$.generation')=r.generation AND json_extract(NEW.decision_json,'$.plan_revision')=r.plan_revision AND json_extract(NEW.decision_json,'$.authority')='management' AND json_extract(NEW.decision_json,'$.action') IN ('accept','return')) BEGIN SELECT RAISE(ABORT,'human decision requires current released acceptance'); END;
PRAGMA user_version=11;
